create table if not exists public.patients (id bigint generated by default as identity primary key, full_name varchar(200) not null, age integer not null, gender varchar(50) not null, created_at timestamp not null default now());
create table if not exists public.appointments (id bigint generated by default as identity primary key, patient_id bigint not null references public.patients(id) on delete cascade, scheduled_for timestamp not null, status varchar(30) not null default 'APPROACHING', provider varchar(200), notes text);
create table if not exists public.billing (id bigint generated by default as identity primary key, patient_id bigint not null references public.patients(id) on delete cascade, amount integer not null, status varchar(30) not null default 'WAITING', description text, received_at timestamp);
create table if not exists public.insurance (id bigint generated by default as identity primary key, patient_id bigint not null references public.patients(id) on delete cascade, provider varchar(200) not null, policy_number varchar(200), group_number varchar(200), eligibility varchar(100), verification_date timestamp, status varchar(50) not null default 'WAITING FOR VERIFICATION', notes text);
create table if not exists public.tasks (id bigint generated by default as identity primary key, patient_id bigint references public.patients(id) on delete cascade, title varchar(200) not null, description text, due_date timestamp, status varchar(30) not null default 'OPEN');
create table if not exists public.followups (id bigint generated by default as identity primary key, patient_id bigint not null references public.patients(id) on delete cascade, reason varchar(250) not null, followup_date timestamp not null, notes text, status varchar(30) not null default 'Upcoming');
create table if not exists public.notes (id bigint generated by default as identity primary key, patient_id bigint references public.patients(id) on delete cascade, author_role varchar(30) not null, note_type varchar(30) not null, content text not null, created_at timestamp not null default now(), updated_at timestamp not null default now());
create table if not exists public.patient_documents (id bigint generated by default as identity primary key, patient_id bigint not null references public.patients(id) on delete cascade, original_name varchar(300) not null, stored_name varchar(300) not null unique, content_type varchar(120), file_size integer not null, uploaded_by varchar(30) not null, created_at timestamp not null default now());
create table if not exists public.activity (id bigint generated by default as identity primary key, actor_role varchar(30) not null, action varchar(200) not null, entity_type varchar(50), entity_id integer, created_at timestamp not null default now());
create table if not exists public.medical_va_credentials (id integer primary key check (id = 1), password_hash text not null, updated_at timestamptz not null default now());
